class Solution(object):
    def findSmallestPath(self, grid, k):
        dp = [[[] for j in xrange(k+1)] for i in xrange(len(grid))]
        for i in xrange(len(grid)):
            for j in xrange(len(grid[0])):
                dp[i][1].append(grid[i][j])
        for i in xrange(len(grid)):
            for j in xrange(len(grid[0])):
                for p in xrange(1, k):
                    for r, c in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
                        if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
                            if len(dp[r][p]) > 0:
                                dp[i][p+1].append(grid[r][c])
                                dp[i][p+1].extend(sorted(dp[r][p]))
                                dp[i][p+1] = [grid[i][j]] + dp[i][p+1]
                                break
        return min(dp[k-1][k])
